<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;颁发机构：$(</span><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> x509 </span><span style="color:#D19A66;">-in</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$file</span><span style="color:#98C379;">&quot; </span><span style="color:#D19A66;">-noout</span><span style="color:#D19A66;"> -issuer</span><span style="color:#D19A66;"> -nameopt</span><span style="color:#98C379;"> RFC2253 </span><span style="color:#ABB2BF;">|</span><span style="color:#61AFEF;"> sed</span><span style="color:#98C379;"> &#39;s/^issuer=//&#39;)&quot;</span></span>
